  ('sd', 'sd.stage_based_cancellation_penalty_gl_8', 'Stage-based cancellation penalty % + GL', 'percent', '%', 'Vizyon 06-sd#8. The stage→penalty-% schedule (owner policy) AND the GL account for cancellation-penalty income'),
  ('sd', 'sd.abc_tier_auto_benefit_package_69', 'ABC tier → auto benefit-package', 'percent', '%', 'Vizyon 06-sd#69. The A/B/C standard-package values: discount%, credit limit, and payment terms for each tier'),
