  ('pp', 'pp.norm_varies_by_material_color_63', 'Norm varies by material/color/lamination combination', 'number', NULL, 'Vizyon 07-pp#63. The actual norm value for each material/color/lamination combination — technologist/owner master-data; an empty lookup is useless.'),
  ('pp', 'pp.algorithm_type_2_8_bo_92', 'Algorithm-type (2-8 bo''lim) auto-classification', 'number', NULL, 'Vizyon 07-pp#92. The tier boundaries: which distinct operation/department-group counts map to which complexity tier (2-8 bo''lim).'),
